    "res_sw_mara.2": { en: "Peat is very old moss. It grows only one millimetre a year. Once it's dried, you can burn it in the stove.", t: [["泥炭", "nítàn", "peat"], ["是", "shì", "is"], ["很", "hěn", "very"], ["老", "lǎo", "old"], ["的", "de", "(particle)"], ["苔藓", "táixiǎn", "moss"], ["。", "", ""], ["它", "tā", "it"], ["一年", "yì nián", "one year"], ["只", "zhǐ", "only"], ["长", "zhǎng", "grows"], ["一", "yì", "one"], ["毫米", "háomǐ", "millimetre"], ["。", "", ""], ["晒干", "shàigān", "dried in the sun"], ["以后", "yǐhòu", "after"], ["，", "", ""], ["可以", "kěyǐ", "can"], ["在", "zài", "in"], ["炉子", "lúzi", "stove"], ["里", "li", "inside"], ["烧", "shāo", "burn"], ["。", "", ""]] },
    "res_sw_mara.3": { en: "One metre of peat is a thousand years old! That's why I only dig a little.", t: [["一", "yì", "one"], ["米", "mǐ", "metre"], ["泥炭", "nítàn", "peat"], ["有", "yǒu", "has"], ["一千", "yìqiān", "a thousand"], ["年", "nián", "years"], ["了", "le", "(already)"], ["！", "", ""], ["所以", "suǒyǐ", "so"], ["我", "wǒ", "I"], ["只", "zhǐ", "only"], ["挖", "wā", "dig"], ["一点儿", "yìdiǎnr", "a little"], ["。", "", ""]] },
    "res_sw_hanne.1": { en: "Welcome! I'm Guihua. I collect herbs in the swamp.", t: [["欢迎", "huānyíng", "welcome"], ["！", "", ""], ["我", "wǒ", "I"], ["是", "shì", "am"], ["桂花", "Guìhuā", "Guihua (name)"], ["。", "", ""], ["我", "wǒ", "I"], ["在", "zài", "in"], ["沼泽", "zhǎozé", "swamp"], ["里", "li", "inside"], ["采", "cǎi", "pick"], ["草药", "cǎoyào", "herbs"], ["。", "", ""]] },
    "res_sw_hanne.2": { en: "The swamp's soil has hardly any food in it, so some plants eat insects, for example the sundew!", t: [["沼泽", "zhǎozé", "swamp"], ["的", "de", "'s"], ["土", "tǔ", "soil"], ["里", "li", "inside"], ["没有", "méiyǒu", "there isn't"], ["什么", "shénme", "much"], ["营养", "yíngyǎng", "nutrients"], ["，", "", ""], ["所以", "suǒyǐ", "so"], ["有的", "yǒude", "some"], ["植物", "zhíwù", "plants"], ["吃", "chī", "eat"], ["虫子", "chóngzi", "insects"], ["，", "", ""], ["比如", "bǐrú", "for example"], ["茅膏菜", "máogāocài", "sundew"], ["！", "", ""]] },
    "res_sw_hanne.3": { en: "The sundew has sticky red drops. A fly that touches them can't get away.", t: [["茅膏菜", "máogāocài", "sundew"], ["有", "yǒu", "has"], ["红红", "hónghóng", "red"], ["的", "de", "(particle)"], ["、", "", ""], ["黏黏", "niánnián", "sticky"], ["的", "de", "(particle)"], ["水珠", "shuǐzhū", "drops"], ["。", "", ""], ["苍蝇", "cāngying", "flies"], ["碰到", "pèngdào", "touch"], ["就", "jiù", "then"], ["走不了", "zǒu bu liǎo", "can't get away"], ["了", "le", "(change)"], ["。", "", ""]] },
    "res_sw_ludger.1": { en: "Hello! I'm Lao Zhou. I make roofs out of reeds.", t: [["你好", "nǐhǎo", "hello"], ["！", "", ""], ["我", "wǒ", "I"], ["是", "shì", "am"], ["老周", "Lǎo Zhōu", "Lao Zhou (name)"], ["。", "", ""], ["我", "wǒ", "I"], ["用", "yòng", "use"], ["芦苇", "lúwěi", "reeds"], ["做", "zuò", "make"], ["屋顶", "wūdǐng", "roofs"], ["。", "", ""]] },
    "res_sw_ludger.2": { en: "We cut the reeds in winter, because then they're dry. A good thatched roof lasts fifty years!", t: [["我们", "wǒmen", "we"], ["冬天", "dōngtiān", "winter"], ["割", "gē", "cut"], ["芦苇", "lúwěi", "reeds"], ["，", "", ""], ["因为", "yīnwèi", "because"], ["那时候", "nà shíhou", "at that time"], ["芦苇", "lúwěi", "reeds"], ["是", "shì", "are"], ["干", "gān", "dry"], ["的", "de", "(particle)"], ["。", "", ""], ["一个", "yí ge", "a"], ["好", "hǎo", "good"], ["的", "de", "(particle)"], ["草", "cǎo", "straw"], ["屋顶", "wūdǐng", "roof"], ["能", "néng", "can"], ["用", "yòng", "be used"], ["五十", "wǔshí", "fifty"], ["年", "nián", "years"], ["！", "", ""]] },
