    "res_sw_ottilie.2": { en: "At night little lights dance over the swamp: will-o'-the-wisps. People say if you follow them, you get lost.", t: [["晚上", "wǎnshang", "at night"], ["，", "", ""], ["沼泽", "zhǎozé", "swamp"], ["上", "shang", "over"], ["有", "yǒu", "there are"], ["小小", "xiǎoxiǎo", "little"], ["的", "de", "(particle)"], ["灯", "dēng", "lights"], ["在", "zài", "(ongoing)"], ["跳舞", "tiàowǔ", "dance"], ["，", "", ""], ["叫", "jiào", "called"], ["“", "", ""], ["鬼火", "guǐhuǒ", "will-o'-the-wisp"], ["”", "", ""], ["。", "", ""], ["人们", "rénmen", "people"], ["说", "shuō", "say"], ["，", "", ""], ["跟着", "gēnzhe", "follow"], ["它", "tā", "it"], ["走", "zǒu", "walk"], ["，", "", ""], ["就", "jiù", "then"], ["会", "huì", "will"], ["迷路", "mílù", "get lost"], ["。", "", ""]] },
    "res_sw_ottilie.3": { en: "Scientists say it's gas from the swamp. But I like the story better!", t: [["科学家", "kēxuéjiā", "scientists"], ["说", "shuō", "say"], ["，", "", ""], ["那", "nà", "that"], ["是", "shì", "is"], ["沼泽", "zhǎozé", "swamp"], ["里", "li", "inside"], ["的", "de", "(particle)"], ["气体", "qìtǐ", "gas"], ["。", "", ""], ["可是", "kěshì", "but"], ["我", "wǒ", "I"], ["更", "gèng", "more"], ["喜欢", "xǐhuan", "like"], ["这个", "zhège", "this"], ["故事", "gùshi", "story"], ["！", "", ""]] },
