    "res_sw_margot.2": { en: "Dragonflies have been around for three hundred million years, earlier than the dinosaurs! Back then some were as big as a bird.", t: [["蜻蜓", "qīngtíng", "dragonflies"], ["已经", "yǐjīng", "already"], ["有", "yǒu", "have"], ["三亿", "sān yì", "three hundred million"], ["年", "nián", "years"], ["了", "le", "(already)"], ["，", "", ""], ["比", "bǐ", "than"], ["恐龙", "kǒnglóng", "dinosaurs"], ["还", "hái", "even"], ["早", "zǎo", "early"], ["！", "", ""], ["那时候", "nà shíhou", "back then"], ["，", "", ""], ["有的", "yǒude", "some"], ["蜻蜓", "qīngtíng", "dragonflies"], ["跟", "gēn", "as"], ["鸟", "niǎo", "a bird"], ["一样", "yíyàng", "the same"], ["大", "dà", "big"], ["。", "", ""]] },
