    "res_sw_gesa.2": { en: "The moss in the swamp is like a sponge and soaks up lots of water. So when it rains hard, the swamp protects the villages.", t: [["沼泽", "zhǎozé", "swamp"], ["里", "li", "inside"], ["的", "de", "(particle)"], ["苔藓", "táixiǎn", "moss"], ["像", "xiàng", "like"], ["海绵", "hǎimián", "a sponge"], ["一样", "yíyàng", "the same"], ["，", "", ""], ["能", "néng", "can"], ["吸", "xī", "soak up"], ["很多", "hěn duō", "a lot of"], ["水", "shuǐ", "water"], ["。", "", ""], ["所以", "suǒyǐ", "so"], ["下", "xià", "fall"], ["大雨", "dàyǔ", "heavy rain"], ["的时候", "de shíhou", "when"], ["，", "", ""], ["沼泽", "zhǎozé", "swamp"], ["保护", "bǎohù", "protects"], ["村子", "cūnzi", "villages"], ["。", "", ""]] },
