    "res_sw_ilse.1": { en: "Good evening! I'm Xiaoyu. I watch the weather every day.", t: [["晚上好", "wǎnshang hǎo", "good evening"], ["！", "", ""], ["我", "wǒ", "I"], ["是", "shì", "am"], ["小雨", "Xiǎoyǔ", "Xiaoyu (name)"], ["。", "", ""], ["我", "wǒ", "I"], ["每天", "měitiān", "every day"], ["看", "kàn", "watch"], ["天气", "tiānqì", "weather"], ["。", "", ""]] },
    "res_sw_ilse.2": { en: "Why is there so much fog here? By day the air is warm and damp. At night it gets cold, and the water in the air turns into tiny drops.", t: [["这里", "zhèli", "here"], ["为什么", "wèishénme", "why"], ["雾", "wù", "fog"], ["那么", "nàme", "so"], ["多", "duō", "much"], ["？", "", ""], ["白天", "báitiān", "by day"], ["空气", "kōngqì", "air"], ["又", "yòu", "both"], ["暖", "nuǎn", "warm"], ["又", "yòu", "and"], ["湿", "shī", "damp"], ["。", "", ""], ["晚上", "wǎnshang", "at night"], ["空气", "kōngqì", "air"], ["变", "biàn", "becomes"], ["冷", "lěng", "cold"], ["，", "", ""], ["空气", "kōngqì", "air"], ["里", "li", "inside"], ["的", "de", "(particle)"], ["水", "shuǐ", "water"], ["就", "jiù", "then"], ["变成", "biànchéng", "turns into"], ["很", "hěn", "very"], ["小", "xiǎo", "small"], ["的", "de", "(particle)"], ["水珠", "shuǐzhū", "drops"], ["。", "", ""]] },
