    "res_sw_konrad.1": { en: "Ah, a guest! I'm Lao Zheng. I look for old things in the swamp.", t: [["啊", "a", "ah"], ["，", "", ""], ["有", "yǒu", "there is"], ["客人", "kèrén", "a guest"], ["！", "", ""], ["我", "wǒ", "I"], ["是", "shì", "am"], ["老郑", "Lǎo Zhèng", "Lao Zheng (name)"], ["。", "", ""], ["我", "wǒ", "I"], ["在", "zài", "in"], ["沼泽", "zhǎozé", "swamp"], ["里", "li", "inside"], ["找", "zhǎo", "look for"], ["老", "lǎo", "old"], ["东西", "dōngxi", "things"], ["。", "", ""]] },
